package com.toainvocationrenamer;

import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Vanilla Tombs of Amascut invocation board labels.
 * Longest vanilla name is 17 characters ("Shaking Things Up").
 */
enum Invocation
{
	TRY_AGAIN("tryAgain", "Try Again"),
	PERSISTENCE("persistence", "Persistence"),
	SOFTCORE_RUN("softcoreRun", "Softcore Run"),
	HARDCORE_RUN("hardcoreRun", "Hardcore Run"),

	WALK_FOR_IT("walkForIt", "Walk for It"),
	JOG_FOR_IT("jogForIt", "Jog for It"),
	RUN_FOR_IT("runForIt", "Run for It"),
	SPRINT_FOR_IT("sprintForIt", "Sprint for It"),

	NEED_SOME_HELP("needSomeHelp", "Need Some Help?"),
	NEED_LESS_HELP("needLessHelp", "Need Less Help?"),
	NO_HELP_NEEDED("noHelpNeeded", "No Help Needed"),

	WALK_THE_PATH("walkThePath", "Walk the Path"),

	PATHSEEKER("pathseeker", "Pathseeker"),
	PATHFINDER("pathfinder", "Pathfinder"),
	PATHMASTER("pathmaster", "Pathmaster"),

	QUIET_PRAYERS("quietPrayers", "Quiet Prayers"),
	DEADLY_PRAYERS("deadlyPrayers", "Deadly Prayers"),

	ON_A_DIET("onADiet", "On a Diet"),
	DEHYDRATION("dehydration", "Dehydration"),
	OVERLY_DRAINING("overlyDraining", "Overly Draining"),

	LIVELY_LARVAE("livelyLarvae", "Lively Larvae"),
	MORE_OVERLORDS("moreOverlords", "More Overlords"),
	BLOWING_MUD("blowingMud", "Blowing Mud"),
	MEDIC("medic", "Medic!"),
	AERIAL_ASSAULT("aerialAssault", "Aerial Assault"),

	NOT_JUST_A_HEAD("notJustAHead", "Not Just a Head"),
	ARTERIAL_SPRAY("arterialSpray", "Arterial Spray"),
	BLOOD_THINNERS("bloodThinners", "Blood Thinners"),
	UPSET_STOMACH("upsetStomach", "Upset Stomach"),

	DOUBLE_TROUBLE("doubleTrouble", "Double Trouble"),
	KEEP_BACK("keepBack", "Keep Back"),
	STAY_VIGILANT("stayVigilant", "Stay Vigilant"),
	FEELING_SPECIAL("feelingSpecial", "Feeling Special?"),

	MIND_THE_GAP("mindTheGap", "Mind the Gap!"),
	GOTTA_HAVE_FAITH("gottaHaveFaith", "Gotta Have Faith"),
	JUNGLE_JAPES("jungleJapes", "Jungle Japes"),
	SHAKING_THINGS_UP("shakingThingsUp", "Shaking Things Up"),
	BOULDERDASH("boulderdash", "Boulderdash"),

	ANCIENT_HASTE("ancientHaste", "Ancient Haste"),
	ACCELERATION("acceleration", "Acceleration"),
	PENETRATION("penetration", "Penetration"),
	OVERCLOCKED("overclocked", "Overclocked"),
	OVERCLOCKED_2("overclocked2", "Overclocked 2"),
	INSANITY("insanity", "Insanity"),

	BLAZING_TOMBS_I("blazingTombsI", "Blazing Tombs I"),
	BLAZING_TOMBS_II("blazingTombsII", "Blazing Tombs II");

	/** Vanilla names fit this many characters; longer custom labels start to clip. */
	static final int DESIGNED_MAX_CHARS = 17;

	private static final Map<String, Invocation> BY_VANILLA;
	private static final Map<String, Invocation> BY_VANILLA_FOLD;

	static
	{
		Map<String, Invocation> exact = new HashMap<>();
		Map<String, Invocation> folded = new HashMap<>();
		for (Invocation invocation : values())
		{
			exact.put(invocation.vanillaName, invocation);
			folded.putIfAbsent(fold(invocation.vanillaName), invocation);
		}
		BY_VANILLA = Collections.unmodifiableMap(exact);
		BY_VANILLA_FOLD = Collections.unmodifiableMap(folded);
	}

	private final String key;
	private final String vanillaName;

	Invocation(String key, String vanillaName)
	{
		this.key = key;
		this.vanillaName = vanillaName;
	}

	String getKey()
	{
		return key;
	}

	String getVanillaName()
	{
		return vanillaName;
	}

	static Invocation matchLabel(String text)
	{
		if (text == null || text.isEmpty())
		{
			return null;
		}

		String trimmed = text.trim();
		if (trimmed.isEmpty())
		{
			return null;
		}

		Invocation exact = BY_VANILLA.get(trimmed);
		if (exact != null)
		{
			return exact;
		}

		return BY_VANILLA_FOLD.get(fold(trimmed));
	}

	private static String fold(String text)
	{
		return text.toLowerCase(Locale.ROOT);
	}
}

package com.toainvocationrenamer;

import java.util.Map;
import net.runelite.client.util.Text;

final class InvocationTexts
{
	private InvocationTexts()
	{
	}

	static String clean(String text)
	{
		if (text == null)
		{
			return "";
		}

		return Text.removeTags(text).trim();
	}

	static String resolveTarget(Invocation invocation, String configured)
	{
		if (configured == null || configured.isBlank())
		{
			return invocation.getVanillaName();
		}

		return configured.trim();
	}

	static Invocation identify(String text, String name, Map<Invocation, String> targets)
	{
		Invocation fromName = Invocation.matchLabel(clean(name));
		if (fromName != null)
		{
			return fromName;
		}

		Invocation fromText = Invocation.matchLabel(clean(text));
		if (fromText != null)
		{
			return fromText;
		}

		return matchConfigured(clean(text), targets);
	}

	static Invocation matchConfigured(String text, Map<Invocation, String> targets)
	{
		if (text == null || text.isEmpty() || targets == null)
		{
			return null;
		}

		Invocation found = null;
		for (Invocation invocation : Invocation.values())
		{
			String target = targets.get(invocation);
			if (target != null && text.equals(target))
			{
				if (found != null)
				{
					return null;
				}

				found = invocation;
			}
		}

		return found;
	}
}

