@PluginDescriptor(
	name = "ToA Invocation Renamer",
	description = "Change the board labels of Tombs of Amascut invocations",
	tags = {"toa", "tombs", "amascut", "invocations", "renamer"}
)
public class ToaInvocationRenamerPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	private final Map<Long, Invocation> bindings = new HashMap<>();

	@Provides
	ToaInvocationRenamerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ToaInvocationRenamerConfig.class);
	}

	@Override
	protected void startUp()
	{
		clientThread.invokeLater(() -> applyLabels());
	}

	@Override
	protected void shutDown()
	{
		clientThread.invoke(() ->
		{
			applyLabels(true);
			bindings.clear();
		});
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		int groupId = event.getGroupId();
		if (groupId == InterfaceID.TOA_INVOCATIONS || groupId == InterfaceID.TOA_PARTYDETAILS)
		{
			bindings.clear();
			clientThread.invokeLater(() -> applyLabels());
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (targetRoots().isEmpty())
		{
			bindings.clear();
			return;
		}

		applyLabels();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ToaInvocationRenamerConfig.GROUP.equals(event.getGroup()))
		{
			clientThread.invokeLater(() -> applyLabels());
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.LOGGING_IN)
		{
			bindings.clear();
		}
	}

	private void applyLabels()
	{
		applyLabels(false);
	}

	private void applyLabels(boolean restore)
	{
		List<Widget> roots = targetRoots();
		if (roots.isEmpty())
		{
			return;
		}

		Map<Invocation, String> targets = currentTargets();
		for (Widget root : roots)
		{
			visitWidgets(root, widget -> applyToWidget(widget, targets, restore));
		}
	}

	private void applyToWidget(Widget widget, Map<Invocation, String> targets, boolean restore)
	{
		String text = widget.getText();
		if (text == null || text.isEmpty())
		{
			return;
		}

		long key = widgetKey(widget);
		Invocation identified = InvocationTexts.identify(text, widget.getName(), targets);
		Invocation invocation = identified != null ? identified : bindings.get(key);
		if (invocation == null)
		{
			return;
		}

		if (identified != null)
		{
			bindings.put(key, identified);
		}

		String target = restore ? invocation.getVanillaName() : targets.get(invocation);
		if (InvocationTexts.clean(text).equals(target))
		{
			return;
		}

		widget.setText(target);
		widget.revalidate();
	}

	private Map<Invocation, String> currentTargets()
	{
		Map<Invocation, String> targets = new EnumMap<>(Invocation.class);
		for (Invocation invocation : Invocation.values())
		{
			targets.put(invocation, InvocationTexts.resolveTarget(
				invocation,
				configManager.getConfiguration(ToaInvocationRenamerConfig.GROUP, invocation.getKey())));
		}
		return targets;
	}

	private List<Widget> targetRoots()
	{
		List<Widget> roots = new ArrayList<>(2);
		Widget party = client.getWidget(InterfaceID.ToaPartydetails.UNIVERSE);
		if (party != null)
		{
			roots.add(party);
		}

		Widget board = client.getWidget(InterfaceID.ToaInvocations.UNIVERSE);
		if (board != null)
		{
			roots.add(board);
		}

		return roots;
	}

	private static long widgetKey(Widget widget)
	{
		return ((long) widget.getId() << 32) | (widget.getIndex() & 0xffffffffL);
	}

	private static void visitWidgets(Widget widget, Consumer<Widget> visitor)
	{
		if (widget == null)
		{
			return;
		}

		visitor.accept(widget);
		visitChildren(widget.getStaticChildren(), visitor);
		visitChildren(widget.getDynamicChildren(), visitor);
		visitChildren(widget.getNestedChildren(), visitor);
	}

	private static void visitChildren(Widget[] children, Consumer<Widget> visitor)
	{
		if (children == null)
		{
			return;
		}

		for (Widget child : children)
		{
			visitWidgets(child, visitor);
		}
	}
}

package com.toainvocationrenamer;

import java.util.HashSet;
import java.util.Set;
import org.junit.Assert;
import org.junit.Test;

public class InvocationTest
{
	@Test
	public void vanillaNamesAreUnique()
	{
		Set<String> names = new HashSet<>();
		for (Invocation invocation : Invocation.values())
		{
			Assert.assertTrue(names.add(invocation.getVanillaName()));
		}
	}

	@Test
	public void configKeysAreUnique()
	{
		Set<String> keys = new HashSet<>();
		for (Invocation invocation : Invocation.values())
		{
			Assert.assertTrue(keys.add(invocation.getKey()));
		}
	}

	@Test
	public void longestVanillaNameFitsDesignedWidth()
	{
		int longest = 0;
		String longestName = "";
		for (Invocation invocation : Invocation.values())
		{
			int length = invocation.getVanillaName().length();
			if (length > longest)
			{
				longest = length;
				longestName = invocation.getVanillaName();
			}
		}

		Assert.assertEquals("Shaking Things Up", longestName);
		Assert.assertEquals(Invocation.DESIGNED_MAX_CHARS, longest);
	}

	@Test
	public void matchLabelFindsVanillaAndIgnoresCase()
	{
		Assert.assertEquals(Invocation.WALK_THE_PATH, Invocation.matchLabel("Walk the Path"));
		Assert.assertEquals(Invocation.WALK_THE_PATH, Invocation.matchLabel("walk the path"));
		Assert.assertEquals(Invocation.WALK_THE_PATH, Invocation.matchLabel("  Walk the Path  "));
		Assert.assertEquals(Invocation.MEDIC, Invocation.matchLabel("Medic!"));
		Assert.assertEquals(Invocation.FEELING_SPECIAL, Invocation.matchLabel("Feeling Special?"));
		Assert.assertNull(Invocation.matchLabel("not an invocation"));
		Assert.assertNull(Invocation.matchLabel(""));
		Assert.assertNull(Invocation.matchLabel("   "));
		Assert.assertNull(Invocation.matchLabel(null));
	}
}

package com.toainvocationrenamer;

import java.util.EnumMap;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class InvocationTextsTest
{
	@Test
	public void cleanStripsTagsAndWhitespace()
	{
		Assert.assertEquals("", InvocationTexts.clean(null));
		Assert.assertEquals("", InvocationTexts.clean("   "));
		Assert.assertEquals("Walk the Path", InvocationTexts.clean("  <col=ff9040>Walk the Path</col>  "));
		Assert.assertEquals("Medic!", InvocationTexts.clean("<col=ffffff>Medic!</col>"));
	}

	@Test
	public void resolveTargetUsesVanillaForBlankConfig()
	{
		Assert.assertEquals("Walk the Path", InvocationTexts.resolveTarget(Invocation.WALK_THE_PATH, null));
		Assert.assertEquals("Walk the Path", InvocationTexts.resolveTarget(Invocation.WALK_THE_PATH, ""));
		Assert.assertEquals("Walk the Path", InvocationTexts.resolveTarget(Invocation.WALK_THE_PATH, "   "));
		Assert.assertEquals("Path of Dust", InvocationTexts.resolveTarget(Invocation.WALK_THE_PATH, "  Path of Dust  "));
	}

	@Test
	public void identifyPrefersStableWidgetNameOverRenamedText()
	{
		Map<Invocation, String> targets = new EnumMap<>(Invocation.class);
		targets.put(Invocation.WALK_THE_PATH, "On a Diet");
		targets.put(Invocation.ON_A_DIET, "On a Diet");

		Assert.assertEquals(
			Invocation.WALK_THE_PATH,
			InvocationTexts.identify("On a Diet", "Walk the Path", targets));
		Assert.assertEquals(
			Invocation.ON_A_DIET,
			InvocationTexts.identify("On a Diet", "On a Diet", targets));
	}

	@Test
	public void identifyFallsBackToUniqueConfiguredText()
	{
		Map<Invocation, String> targets = allVanillaTargets();
		targets.put(Invocation.MEDIC, "Nurse!");

		Assert.assertEquals(Invocation.MEDIC, InvocationTexts.identify("Nurse!", "", targets));
		Assert.assertNull(InvocationTexts.identify("not an invocation", "", targets));
	}

	@Test
	public void matchConfiguredIgnoresAmbiguousCustomNames()
	{
		Map<Invocation, String> targets = allVanillaTargets();
		targets.put(Invocation.WALK_THE_PATH, "Shared");
		targets.put(Invocation.ON_A_DIET, "Shared");

		Assert.assertNull(InvocationTexts.matchConfigured("Shared", targets));
		Assert.assertEquals(Invocation.MEDIC, InvocationTexts.matchConfigured("Medic!", targets));
	}

	@Test
	public void identifyHandlesTaggedVanillaLabels()
	{
		Map<Invocation, String> targets = allVanillaTargets();
		Assert.assertEquals(
			Invocation.FEELING_SPECIAL,
			InvocationTexts.identify("<col=ff9040>Feeling Special?</col>", "", targets));
	}

	private static Map<Invocation, String> allVanillaTargets()
	{
		Map<Invocation, String> targets = new EnumMap<>(Invocation.class);
		for (Invocation invocation : Invocation.values())
		{
			targets.put(invocation, invocation.getVanillaName());
		}
		return targets;
	}
}

package com.toainvocationrenamer;

import java.lang.reflect.Method;
import java.util.HashSet;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import org.junit.Assert;
import org.junit.Test;

public class ToaInvocationRenamerConfigTest
{
	@Test
	public void everyInvocationHasAConfigItem() throws Exception
	{
		Set<String> configKeys = new HashSet<>();
		for (Method method : ToaInvocationRenamerConfig.class.getDeclaredMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item != null)
			{
				Assert.assertTrue("duplicate key " + item.keyName(), configKeys.add(item.keyName()));
			}
		}

		for (Invocation invocation : Invocation.values())
		{
			Assert.assertTrue(
				"missing config key for " + invocation,
				configKeys.contains(invocation.getKey()));
		}

		Assert.assertEquals(Invocation.values().length, configKeys.size());
	}
}

